 dangerous_good_toxic, dangerous_good_hazard_symbols, dangerous_good_storage_requirements, dangerous_good_handling_instructions, dangerous_good_country_origin FROM shipment_aud WHERE dangerous_good_un_number IS NOT NULL;
UPDATE shipment SET dangerous_good_id = shipment_id WHERE dangerous_good_un_number IS NOT NULL; UPDATE shipment_rd SET dangerous_good_id = shipment_id WHERE dangerous_good_un_number IS NOT NULL; UPDATE shipment_aud SET dangerous_good_id = shipment_id WHERE dangerous_good_un_number IS NOT NULL;
